from enum import Enum
from core.event_bus.models import SystemEvent


class NukeType(Enum):
    MASS_BAN = "MASS_BAN"
    CHANNEL_DELETE = "CHANNEL_DELETE"
    ROLE_DELETE = "ROLE_DELETE"
    WEBHOOK_SPAM = "WEBHOOK_SPAM"


class NukeDetectedEvent(SystemEvent):
    """Event explicitly generated by AntiNukeService when a threshold breaches."""

    actor_id: int
    nuke_type: NukeType
    burst_count: int
    time_window_seconds: int
